// TranscriptServiceHandler is an implementation of the elephant.stream.v1.TranscriptService
// service.
type TranscriptServiceHandler interface {
	// ClaimJob leases the job of the kinds asked for that has waited
	// longest, live jobs before final ones, waiting for one when there is
	// none yet. A job whose lease has run out may be claimed again by
	// another worker, which gets a new lease token; the old one is refused
	// from then on.
	ClaimJob(context.Context, *connect.Request[v1.ClaimJobRequest]) (*connect.Response[v1.ClaimJobResponse], error)
	// RenewLease extends a lease by the lease time from now.
	RenewLease(context.Context, *connect.Request[v1.RenewLeaseRequest]) (*connect.Response[v1.RenewLeaseResponse], error)
	// ReleaseJob ends a lease: the job is done, unsupported, failed, or
	// given back for another worker to claim.
	ReleaseJob(context.Context, *connect.Request[v1.ReleaseJobRequest]) (*connect.Response[v1.ReleaseJobResponse], error)
	// StartRun opens a run for the job: the event's one live transcript, or a
	// final job's transcript, diarization or attribution. The live job of an
	// AUDIO_LAYOUT_CALL_STEREO event also makes the event's one live
	// attribution, of the live transcript, attributing the words by channel
	// as they commit. The live runs are made once per event and returned
	// again to every later StartRun of the live job, for a worker taking
	// over from one that stopped; resume them from GetRunProgress. A final
	// job's StartRun always makes a new run.
	StartRun(context.Context, *connect.Request[v1.StartRunRequest]) (*connect.Response[v1.StartRunResponse], error)
	// GetRunProgress says where a run stands, for a worker resuming it.
	GetRunProgress(context.Context, *connect.Request[v1.GetRunProgressRequest]) (*connect.Response[v1.GetRunProgressResponse], error)
	// CommitWords appends words to a transcript run. Committed words are
	// never revised.
	CommitWords(context.Context, *connect.Request[v1.CommitWordsRequest]) (*connect.Response[v1.CommitWordsResponse], error)
	// PutSpeakerSpans appends speaker spans to a diarization run.
	PutSpeakerSpans(context.Context, *connect.Request[v1.PutSpeakerSpansRequest]) (*connect.Response[v1.PutSpeakerSpansResponse], error)
	// PutAttributions records the speaker of words of a transcript run in
	// an attribution run.
	PutAttributions(context.Context, *connect.Request[v1.PutAttributionsRequest]) (*connect.Response[v1.PutAttributionsResponse], error)
	// CompleteRun makes a final run visible; until then no reader sees it.
	// Completing the live transcript ends the StreamTranscript calls that
	// follow it. Completing a completed run changes nothing.
	CompleteRun(context.Context, *connect.Request[v1.CompleteRunRequest]) (*connect.Response[v1.CompleteRunResponse], error)
	// StreamTranscript streams the live words of an event as they commit,
	// from an ordinal, and ends when the live run completes, or when the
	// live job ends without completing it. It waits for the live run to
	// start, and ends at once for an event that will have none: an uploaded
	// recording, one that has ended without a live job to make it, or one
	// whose live job was released as unsupported or failed.
	StreamTranscript(context.Context, *connect.Request[v1.StreamTranscriptRequest], *connect.ServerStream[v1.StreamTranscriptResponse]) error
	// GetTranscript returns the words of an event from the layer asked for,
	// each attributed to a speaker when an attribution of that run exists.
	// By default it is the completed final layer of the event's current
	// archive generation with its corrections applied, and the live run
	// until there is one.
	GetTranscript(context.Context, *connect.Request[v1.GetTranscriptRequest]) (*connect.Response[v1.GetTranscriptResponse], error)
	// GetTranscriptStatus says where an event's transcription stands, for
	// the media center.
	GetTranscriptStatus(context.Context, *connect.Request[v1.GetTranscriptStatusRequest]) (*connect.Response[v1.GetTranscriptStatusResponse], error)
	// CorrectWords replaces a stretch of words of a completed final
	// transcript run with new text, recording who corrected it and when. The
	// machine's words are never changed. A later correction of an
	// overlapping stretch supersedes it.
	CorrectWords(context.Context, *connect.Request[v1.CorrectWordsRequest]) (*connect.Response[v1.CorrectWordsResponse], error)
	// RevertCorrection withdraws a correction. Corrections it superseded
	// stand again. Reverting a reverted correction changes nothing.
	RevertCorrection(context.Context, *connect.Request[v1.RevertCorrectionRequest]) (*connect.Response[v1.RevertCorrectionResponse], error)
	// ReassignSpeaker attributes a stretch of words of a completed final
	// transcript run to another speaker, an existing label of the run or a
	// new one, recording who did it and when. The machine's attribution is
	// never changed. Of the reassignments covering a word the latest decides
	// its speaker, so a later reassignment of an overlapping stretch
	// supersedes an earlier one for the words they share.
	ReassignSpeaker(context.Context, *connect.Request[v1.ReassignSpeakerRequest]) (*connect.Response[v1.ReassignSpeakerResponse], error)
	// RevertSpeakerReassignment withdraws a reassignment. The words it
	// covered get their speaker from the reassignments before it, or from the
	// machine's attribution, again. Reverting a reverted reassignment changes
	// nothing.
	RevertSpeakerReassignment(context.Context, *connect.Request[v1.RevertSpeakerReassignmentRequest]) (*connect.Response[v1.RevertSpeakerReassignmentResponse], error)
	// NameSpeaker gives a speaker label of a completed final transcript run a
	// display name, and optionally links it to a person entity of the
	// repository, or clears them. Each request sets both.
	NameSpeaker(context.Context, *connect.Request[v1.NameSpeakerRequest]) (*connect.Response[v1.NameSpeakerResponse], error)
	// InsertSegment adds text the transcription left out, such as an
	// interjection spoken over someone else, to a completed final transcript
	// run: a segment spoken by a speaker of the run, or a new one, between
	// two of its words or before the first, recording who added it and when.
	// The machine's words are never changed. Segments inserted at the same
	// place are read in the order they were made.
	InsertSegment(context.Context, *connect.Request[v1.InsertSegmentRequest]) (*connect.Response[v1.InsertSegmentResponse], error)
	// RevertInsertedSegment withdraws an inserted segment. Reverting a
	// reverted segment changes nothing.
	RevertInsertedSegment(context.Context, *connect.Request[v1.RevertInsertedSegmentRequest]) (*connect.Response[v1.RevertInsertedSegmentResponse], error)
	// SkipWords marks a stretch of words of a completed final transcript run
	// as skipped: talk that doesn't matter, which a reader collapses and a
	// player passes over until it is opened. It records who skipped it and
	// when, and the stretch's time range. The machine's words are never
	// changed, and skips may overlap.
	SkipWords(context.Context, *connect.Request[v1.SkipWordsRequest]) (*connect.Response[v1.SkipWordsResponse], error)
	// RevertSkip withdraws a skip. Reverting a reverted skip changes nothing.
	RevertSkip(context.Context, *connect.Request[v1.RevertSkipRequest]) (*connect.Response[v1.RevertSkipResponse], error)
	// SplitParagraph makes a stretch of words of a completed final transcript
	// run a paragraph of its own: one starts at its first word, and another
	// after its last. It records who split it and when.
	SplitParagraph(context.Context, *connect.Request[v1.SplitParagraphRequest]) (*connect.Response[v1.SplitParagraphResponse], error)
	// MergeParagraphs keeps a stretch of words of a completed final
	// transcript run in one paragraph, the paragraphs it touches whole: the
	// stretch is widened to the paragraphs its first and last words are in.
	// Refused when the words don't all have the same speaker. A later change
	// of speaker inside it still starts a paragraph, as an inserted segment
	// does.
	MergeParagraphs(context.Context, *connect.Request[v1.MergeParagraphsRequest]) (*connect.Response[v1.MergeParagraphsResponse], error)
	// RevertParagraphEdit withdraws a split or a merge. Reverting a reverted
	// edit changes nothing.
	RevertParagraphEdit(context.Context, *connect.Request[v1.RevertParagraphEditRequest]) (*connect.Response[v1.RevertParagraphEditResponse], error)
	// MarkProofread records that paragraphs of a completed final transcript
	// run were proofread, by whom and when: the paragraphs a stretch of words
	// touches, whole, and inserted segments. A paragraph counts as proofread
	// while standing marks cover all of it. A change to anything a mark
	// covers made after it, a correction, a reassignment, a skip, a segment
	// inserted inside it, a paragraph edit, or the revert of one, makes the
	// mark stale.
	MarkProofread(context.Context, *connect.Request[v1.MarkProofreadRequest]) (*connect.Response[v1.MarkProofreadResponse], error)
	// RevertProofread withdraws a proofread mark. Reverting a reverted mark
	// changes nothing.
	RevertProofread(context.Context, *connect.Request[v1.RevertProofreadRequest]) (*connect.Response[v1.RevertProofreadResponse], error)
	// SetSpeakerInterviewer says whether a speaker label of a completed final
	// transcript run is an interviewer, whose words a published interview
	// sets in bold. The journalist of a call is one until someone says
	// otherwise.
	SetSpeakerInterviewer(context.Context, *connect.Request[v1.SetSpeakerInterviewerRequest]) (*connect.Response[v1.SetSpeakerInterviewerResponse], error)
	// AddBookmark marks a stretch of an event's transcript for finding again,
	// by its time range on the program-date-time timeline, so that it points
	// at the same words in the live and the final transcript. It records who
	// set it and when, and the text the words read, which names it. Any
	// layer of a transcript can be bookmarked, while the event is live too.
	AddBookmark(context.Context, *connect.Request[v1.AddBookmarkRequest]) (*connect.Response[v1.AddBookmarkResponse], error)
	// ListBookmarks returns an event's standing bookmarks, everyone's, in the
	// order they come in the recording.
	ListBookmarks(context.Context, *connect.Request[v1.ListBookmarksRequest]) (*connect.Response[v1.ListBookmarksResponse], error)
	// RemoveBookmark withdraws a bookmark. Removing a removed bookmark
	// changes nothing.
	RemoveBookmark(context.Context, *connect.Request[v1.RemoveBookmarkRequest]) (*connect.Response[v1.RemoveBookmarkResponse], error)
}

